import argparse,json
from pathlib import Path
import sympy as s
ap=argparse.ArgumentParser();ap.add_argument('--output',required=True);a=ap.parse_args();r,k=s.symbols('r kappa',positive=True);gb=1/r**2;g=(1+s.sqrt(1+4*r*r))/(2*r*r);u=g-gb;M=s.simplify(r*r*u);rho=s.simplify(s.diff(M,r)/r**2);amp=s.sqrt(2)*r**(-s.Rational(1,2))*(1+4*r*r)**(-s.Rational(1,4));lap=s.simplify((s.diff(amp,r,2)+2/r*s.diff(amp,r))/amp);expected=-(1+24*r*r)/(4*r*r*(1+4*r*r)**2);mu=-k*lap/2;mp=s.factor(s.diff(mu,r));target=-k*(1+12*r*r+192*r**4)/(4*r**3*(1+4*r*r)**3);assert s.simplify(g-u/(1-u))==0;assert s.simplify(rho-2/(r*s.sqrt(1+4*r*r)))==0;assert s.simplify(lap-expected)==0;assert s.simplify(mp-target)==0;delta=mp/(g*(2+g));limit=s.limit(r**3*delta/(k*g),r,s.oo);assert limit==-s.Rational(3,8);units=json.loads(Path('physical_completion_2026_10_25/run_units/results.json').read_text());scale=(units['canonical_kinetic_Q_m4_per_s2']/9.3603e-11)**(1/3)/3.085677581491367e19;out={'claim':'The exact point-source galaxy-law density is not a stationary pure-T bulk solution with nonzero canonical material stiffness and no other bulk force. Interface-localized terms cannot cancel the spatially varying bulk residual.','hypotheses':['spherical point baryon source outside r=0','pure T region, no enclosed F source','canonical sqrt-density gradient energy kappa/2','carrier and internal angles constant in region','all additional modifications localized outside the region'],'rho_law':str(rho),'laplacian_amplitude_ratio':str(expected),'bulk_chemical_force_residual_mu_prime':str(target),'counterexample_at_r1_over_kappa':str(s.simplify(target.subs(r,1)/k)),'formal_first_order_delta_g':str(delta),'deep_point_source_limit_delta_g_over_g':str(-s.Rational(3,8)*k/r**3),'natural_Q_a0_length_kpc':scale,'checks':'All displayed identities simplify exactly to zero; asymptotic limit exactly -3/8.','non_claims':['Not a no-go for other bulk interactions, small observational corrections, mixed phases or other particle interpretations','First-order correction is an interior formal expansion, not a global existence or boundary-layer estimate','Natural length is not a predicted core radius for arbitrary baryonic profiles'],'sympy_version':s.__version__};Path(a.output).write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2))
